__NUXT_JSONP__("/fr/teachers", {data:[{details:{slug:"fr",pageTitle:"Les classes de MLI et ses enseignants | Mentor Language Institute",pageDescription:"Dans les cours d'anglais général, les étudiants acquièrent des compétences pratiques en utilisant les faits du monde réel tels que des articles sur Twitter, des conférences TED et des clips vidéo.",title:"Les classes de MLI et ses enseignants",image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fmli-student-teachers.jpg",lists:[{title:"Les cours mettent l'accent sur les compétences pratiques",description:["Dans les cours d'anglais général, les étudiants acquièrent des compétences pratiques en utilisant les faits du monde réel tels que des articles sur Twitter, des conférences TED et des clips vidéo. En utilisant ces matériaux, les élèves acquièrent systématiquement des compétences en grammaire, l'écriture, la lecture, le vocabulaire, l'écoute et la parole.","En outre, le TOEFL® et d'autres cours de préparation aux examens fournissent des stratégies pour résoudre les problèmes avec leurs propres méthodes."]},{title:"Les enseignants de MLI",description:["Chaque année, 1200 étudiants finissent leur programmes à MLI, ce qui témoigne de la qualité de nos enseignants. \u003Cbr \u002F\u003E Nous nous efforçons constamment d'améliorer les compétences des instructeurs grâce à des observations, des évaluations et des ateliers d'amélioration professionnelle."],checklist:[{title:"Conditions d'embauche (liste pour l'embauche d'enseignants)",lists:["Diplômé d'université de quatre ans","3 ans d'expérience en tant qu'enseignant d'anglais","Qualification d'enseignement tel que le TESOL","Connaissance d'examens tels que TOEFL®\u002FGMAT®","De solides compétences en communication","Passion et engagement pour l'enseignement"]},{title:"Méthode de sélection",lists:["CV et diplôme","Test de grammaire anglaise","Interview","Exemple de Leçon"],note:"Le taux d'embauche est inférieur à 20%."}]},{title:"Système de formation et d'évaluation",description:["À MLI, toutes les 12 semaines nous vérifions les trois éléments suivants pour maintenir la qualité de l'enseignant."],listType:"decimal",lists:["Les élèves évaluent nos livres et nos enseignants. Les enseignants recevant un taux de satisfaction de 85% ou moins suivent une formation d'amélioration professionnelle.","Observation des cours et retour d'information fournie par l'équipe universitaire supérieure","Développement professionnel et ateliers de formation pour améliorer l'enseignement"],note:"La direction et les instructeurs s'efforcent d'améliorer la qualité de l'éducation tous les jours!"}],teachers:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-julie.jpg",name:"Julie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-brian.jpg",name:"Brian"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kelsey.jpg",name:"Kelsey"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shawna.jpg",name:"Shawna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-benjamin.jpg",name:"Benjamin"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kyle.jpg",name:"Kyle"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-lindsay.jpg",name:"Lindsay"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-leo.jpg",name:"Leo"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-alex.jpg",name:"Alex"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-carl.jpg",name:"Carl"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shenna.jpg",name:"Shenna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-bonnie.jpg",name:"Bonnie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-patrick.jpg",name:"Patrick"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-hubert.jpg",name:"Hubert"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-matt.jpg",name:"Matt"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Maribel.jpg",name:"Maribel"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Joan.jpg",name:"Joan"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Sara.jpg",name:"Sara"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Tom.jpg",name:"Tom"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Gannon.jpg",name:"Gannon"}],dir:"\u002Fteachers",path:"\u002Fteachers\u002Ffr",extension:".json",createdAt:"2026-10-22T16:31:31.169Z",updatedAt:"2025-05-26T12:06:27.929Z"}}],fetch:{},mutations:void 0});